//
// Min/Max = count_min/count_max ของช่องนั้น (0 = ใส่หรือไม่ใส่ก็ได้)
// Tags/Materials = required_tags/required_materials ตามข้อมูลของเกม
// (ไอเทมที่ server รุ่นนี้สร้างยังไม่มี tag ติดตัว จึงใช้เป็นข้อมูลประกอบ/log เท่านั้น)
public static class RecipeRequirements
{
    public sealed class Slot
    {
        public readonly string Id;
        public readonly int Min;
        public readonly int Max;
        public readonly TagRequirement[] Tags;
        public readonly TagRequirement[] Materials;

        public Slot(string id, int min, int max, TagRequirement[] tags, TagRequirement[] materials)
        {
            Id = id;
            Min = min;
            Max = max;
            Tags = tags;
            Materials = materials;
        }
    }

    private static Slot S(string id, int min, int max, TagRequirement[] tags = null, TagRequirement[] materials = null)
    {
        return new Slot(id, min, max, tags, materials);
    }

