    /// <summary>ช่องวัตถุดิบของสูตรนี้ — false ถ้าไม่มีสูตรนี้ในเกม</summary>
    public static bool TryGet(string recipeId, out Slot[] slots)
    {
        slots = null;
        return !string.IsNullOrEmpty(recipeId) && Recipes.TryGetValue(recipeId, out slots);
    }
